import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        long mx = 0;
        for (int i = 0; i < n; i++) mx = Math.max(mx, a[i] = nextLong());
        int cnt = 0;
        long[] powers = new long[40];
        for (long p = 1; p <= 2 * mx; p *= 3) powers[cnt++] = p;
        // seen[] counts earlier prices; values are compressed so a lookup is a binary search.
        long[] uniq = a.clone();
        Arrays.sort(uniq);
        int u = 0;
        for (int i = 0; i < n; i++) if (i == 0 || uniq[i] != uniq[i - 1]) uniq[u++] = uniq[i];
        long[] seen = new long[u];
        long answer = 0;
        for (long v : a) {
            for (int j = 0; j < cnt; j++) {
                int at = Arrays.binarySearch(uniq, 0, u, powers[j] - v);
                if (at >= 0) answer += seen[at];
            }
            seen[Arrays.binarySearch(uniq, 0, u, v)]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	var mx int64
	for i := range a {
		a[i] = nextInt()
		mx = max(mx, a[i])
	}
	var powers []int64
	for p := int64(1); p <= 2*mx; p *= 3 {
		powers = append(powers, p)
	}
	// seen[] counts earlier prices; values are compressed so a lookup is a binary search.
	uniq := slices.Clone(a)
	slices.Sort(uniq)
	uniq = slices.Compact(uniq)
	seen := make([]int64, len(uniq))
	var answer int64
	for _, v := range a {
		for _, p := range powers {
			if at, ok := slices.BinarySearch(uniq, p-v); ok {
				answer += seen[at]
			}
		}
		at, _ := slices.BinarySearch(uniq, v)
		seen[at]++
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
